def standard_gob(x, y):
    return (
        (x & 0x0f) |
        ((y & 1) << 4) |
        (((x >> 4) & 1) << 5) |
        (((y >> 1) & 1) << 6) |
        (((x >> 5) & 1) << 7) |
        (((y >> 2) & 1) << 8)
    )

def buggy_gob(x, y):
    return (x & 0xF) | ((y & 1) << 4) | (((x >> 4) & 1) << 5) | (((x >> 5) & 1) << 6) | (((y >> 1) & 3) << 7)

diffs = 0
for y in range(8):
    for x in range(64):
        s = standard_gob(x, y)
        b = buggy_gob(x, y)
        if s != b:
            diffs += 1
            if diffs <= 5:
                print(f'Diff at x={x}, y={y}: standard={s}, buggy={b}')

print('Total diffs out of 512:', diffs)
