    return (((x % 64) // 32) * 256 + ((y % 8) // 2) * 64
            + ((x % 32) // 16) * 32 + (y % 2) * 16 + (x % 16))

def gob_fixed(x, y):
    return (
        (x & 0x0F) |
        ((y & 1) << 4) |
        (((x >> 4) & 1) << 5) |
        (((y >> 1) & 1) << 6) |
        (((y >> 2) & 1) << 7) |
        (((x >> 5) & 1) << 8)
