import struct

with open(r'extracted_switch_usa\sys\sysp', 'rb') as f:
    sysp = f.read()

def walk_ofs3(buf, label):
    if buf[:4] != b'OFS3': return
    hdr_sz, unk, dsz = struct.unpack_from('<III', buf, 4)
    cnt = struct.unpack_from('<I', buf, 16)[0]
    has_names = (unk & 2) != 0
    for i in range(cnt):
        if has_names:
            off, sz, noff = struct.unpack_from('<III', buf, 20 + i*12)
            end = buf.find(b'\x00', 16 + noff)
            name = buf[16 + noff : end].decode('utf-8', 'ignore')
        else:
            off, sz = struct.unpack_from('<II', buf, 20 + i*8)
            name = f'sub_{i}'
        sub = buf[16 + off : 16 + off + sz]
        if sub[:4] == b'OFS3':
            walk_ofs3(sub, f'{label}/{name}')
        elif name.endswith('_frame.dat'):
            fcnt, pad = struct.unpack_from('<II', sub, 0)
            f1_recs = []
            for j in range(fcnt):
                rec = sub[8 + j*24 : 8 + (j+1)*24]
                x, y, w, h = struct.unpack_from('<hhhh', rec, 0)
                align, fid = rec[0x14], rec[0x15]
                if fid == 1:
                    f1_recs.append(f'[{j}] pos=({x},{y}) {w}x{h} align={align}')
            if f1_recs:
                print(f'{label}/{name}:')
                for r in f1_recs:
                    print('  ', r)

walk_ofs3(sysp, 'sysp')
